// MARK: - Convenient Localized String Extension

extension String {
    /// Returns the localized string for the current app language.
    @MainActor
    public var localized: String {
        L10n.tr(self)
    }

    /// Returns the localized string formatted with the provided arguments.
    @MainActor
    public func localizedFormat(_ arguments: CVarArg...) -> String {
        String(format: self.localized, arguments: arguments)
    }

    /// Returns the localized string formatted with the provided arguments (static helper).
    @MainActor
    public static func localizedFormat(_ formatKey: String, _ arguments: CVarArg...) -> String {
        String(format: formatKey.localized, arguments: arguments)
    }
}
